request_template:
{
  "model": "{{ model }}",
  "prompt": {{ prompt_json }},
  {% if negative_prompt %}"negative_prompt": {{ negative_prompt_json }},
{% endif %}
  "size": "{{ size }}",
  "aspect_ratio": "{{ aspect_ratio }}",
  "seconds": "{{ seconds }}",
  "cfg_scale": {{ cfg_scale }},
  "mode": "{{ mode }}",
  "n": {{ n }}
  {% if reference_images and reference_images|length > 0 %},
  "images": [
    {% for img in reference_images %}{{ img | tojson }}{% if not loop.last %}, {% endif %}
    {% endfor %}
  ]
  {% endif %}
}
